ALTER TABLE public.tasks ADD COLUMN recurrence text NOT NULL DEFAULT 'once', ADD COLUMN weekdays integer[] NOT NULL DEFAULT '{}', ADD COLUMN recurrence_state text NOT NULL DEFAULT 'enabled';
CREATE TABLE public.task_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES public.tasks(id),effective_from date NOT NULL,effective_until date,title text NOT NULL,description text,owner_id uuid,creator_id uuid,priority public.task_priority NOT NULL,due_time time,recurrence text NOT NULL,weekdays integer[] NOT NULL DEFAULT '{}',enabled boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_revisions TO authenticated; GRANT ALL ON public.task_revisions TO service_role;
ALTER TABLE public.task_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "revision executive read" ON public.task_revisions FOR SELECT TO authenticated USING(public.is_executive());
CREATE TABLE public.task_executions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_id uuid NOT NULL REFERENCES public.tasks(id),revision_id uuid REFERENCES public.task_revisions(id),scheduled_date date,due_time time,title text NOT NULL,description text,owner_id uuid,creator_id uuid,priority public.task_priority NOT NULL DEFAULT 'medium',status text NOT NULL DEFAULT 'todo',recurring boolean NOT NULL DEFAULT false,completed_at timestamptz,skip_state text NOT NULL DEFAULT 'none',skip_reason text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_executions TO authenticated; GRANT ALL ON public.task_executions TO service_role;
ALTER TABLE public.task_executions ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX task_execution_date_unique ON public.task_executions(task_id,scheduled_date) WHERE status<>'cancelled';
CREATE POLICY "execution own read" ON public.task_executions FOR SELECT TO authenticated USING(public.is_active_member(auth.uid()) AND (public.is_executive() OR owner_id=auth.uid()));
CREATE TABLE public.task_execution_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),execution_id uuid NOT NULL REFERENCES public.task_executions(id),actor_id uuid,action text NOT NULL,body text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.task_execution_events TO authenticated; GRANT ALL ON public.task_execution_events TO service_role;
ALTER TABLE public.task_execution_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "execution events own read" ON public.task_execution_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.task_executions e WHERE e.id=execution_id));
INSERT INTO public.task_revisions(task_id,effective_from,title,description,owner_id,creator_id,priority,due_time,recurrence,enabled) SELECT id,coalesce(due_date,(created_at AT TIME ZONE 'America/Bogota')::date),title,description,owner_id,creator_id,priority,due_time,'once',archived_at IS NULL FROM public.tasks;
INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,due_time,title,description,owner_id,creator_id,priority,status,completed_at) SELECT t.id,r.id,t.due_date,t.due_time,t.title,t.description,t.owner_id,t.creator_id,t.priority,CASE WHEN t.archived_at IS NOT NULL THEN 'cancelled' ELSE t.status::text END,t.completed_at FROM public.tasks t JOIN public.task_revisions r ON r.task_id=t.id;
INSERT INTO public.task_execution_events(execution_id,actor_id,action,body,created_at) SELECT e.id,c.author_id,'comment',c.body,c.created_at FROM public.task_comments c JOIN public.task_executions e ON e.task_id=c.task_id;
INSERT INTO public.task_execution_events(execution_id,action,created_at) SELECT id,'completed',completed_at FROM public.task_executions WHERE completed_at IS NOT NULL;
CREATE OR REPLACE FUNCTION public.can_see_task(_task_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_active_member(auth.uid()) AND EXISTS(SELECT 1 FROM public.tasks WHERE id=_task_id AND (public.is_executive() OR owner_id=auth.uid())) $$;
DO $$ DECLARE p record; BEGIN FOR p IN SELECT tablename,policyname FROM pg_policies WHERE schemaname='public' AND tablename IN ('tasks','task_comments') LOOP EXECUTE format('DROP POLICY %I ON public.%I',p.policyname,p.tablename); END LOOP; END $$;
CREATE POLICY "tasks owner read" ON public.tasks FOR SELECT TO authenticated USING(public.can_see_task(id));
CREATE POLICY "tasks exec insert" ON public.tasks FOR INSERT TO authenticated WITH CHECK(public.is_active_member(auth.uid()) AND public.is_executive());
CREATE POLICY "tasks exec update" ON public.tasks FOR UPDATE TO authenticated USING(public.is_active_member(auth.uid()) AND public.is_executive()) WITH CHECK(public.is_executive());
CREATE POLICY "comments owner read" ON public.task_comments FOR SELECT TO authenticated USING(public.can_see_task(task_id));
CREATE POLICY "comments owner insert" ON public.task_comments FOR INSERT TO authenticated WITH CHECK(author_id=auth.uid() AND public.can_see_task(task_id));
CREATE OR REPLACE FUNCTION public.materialize_task_executions() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date := (now() AT TIME ZONE 'America/Bogota')::date; BEGIN
INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,due_time,title,description,owner_id,creator_id,priority,recurring)
SELECT r.task_id,r.id,d::date,r.due_time,r.title,r.description,r.owner_id,r.creator_id,r.priority,true FROM public.task_revisions r CROSS JOIN LATERAL generate_series(r.effective_from::timestamp,least(coalesce(r.effective_until,today),today)::timestamp,interval '1 day') d WHERE r.enabled AND r.recurrence<>'once' AND (r.recurrence='daily' OR extract(dow FROM d)::integer=ANY(r.weekdays)) ON CONFLICT(task_id,scheduled_date) WHERE status<>'cancelled' DO NOTHING; END $$;
REVOKE ALL ON FUNCTION public.materialize_task_executions() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.task_agenda(_date date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE today date := (now() AT TIME ZONE 'America/Bogota')::date; result jsonb; BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; PERFORM public.materialize_task_executions();
SELECT coalesce(jsonb_agg(to_jsonb(e)||jsonb_build_object('projected',false) ORDER BY e.scheduled_date,e.due_time),'[]'::jsonb) INTO result FROM public.task_executions e WHERE (public.is_executive() OR e.owner_id=auth.uid()) AND (e.scheduled_date=_date OR e.scheduled_date IS NULL OR (e.status NOT IN ('done','skipped','cancelled') AND e.due_time IS NOT NULL AND (e.scheduled_date+e.due_time)<(now() AT TIME ZONE 'America/Bogota')));
IF _date>today THEN SELECT result||coalesce(jsonb_agg(jsonb_build_object('id',r.id::text||':'||_date::text,'task_id',r.task_id,'scheduled_date',_date,'due_time',r.due_time,'title',r.title,'description',r.description,'owner_id',r.owner_id,'creator_id',r.creator_id,'priority',r.priority,'status','todo','recurring',true,'skip_state','none','projected',true)),'[]'::jsonb) INTO result FROM public.task_revisions r WHERE r.enabled AND r.recurrence<>'once' AND r.effective_from<=_date AND (r.effective_until IS NULL OR r.effective_until>=_date) AND (r.recurrence='daily' OR extract(dow FROM _date)::integer=ANY(r.weekdays)) AND (public.is_executive() OR r.owner_id=auth.uid()); END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.task_execution_action(_id uuid,_action text,_body text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.task_executions; exec boolean := public.is_executive(); BEGIN
IF NOT public.is_active_member(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF; SELECT * INTO e FROM public.task_executions WHERE id=_id FOR UPDATE; IF NOT FOUND OR NOT (exec OR coalesce(e.owner_id=auth.uid(),false)) THEN RAISE EXCEPTION 'Not authorized'; END IF;
IF e.status='cancelled' THEN RAISE EXCEPTION 'Execution cancelled'; END IF;
IF _action='comment' THEN IF nullif(trim(_body),'') IS NULL OR length(_body)>4000 THEN RAISE EXCEPTION 'Invalid comment'; END IF;
ELSIF _action='complete' THEN IF e.status IN ('done','skipped') THEN RETURN; END IF; IF e.scheduled_date>(now() AT TIME ZONE 'America/Bogota')::date THEN RAISE EXCEPTION 'Cannot complete future execution'; END IF; UPDATE public.task_executions SET status='done',completed_at=now(),skip_state='none' WHERE id=_id;
ELSIF _action='reopen' THEN IF e.status<>'done' THEN RAISE EXCEPTION 'Only completed executions can reopen'; END IF; UPDATE public.task_executions SET status='todo',skip_state='none' WHERE id=_id;
ELSIF _action='request_skip' THEN IF NOT e.recurring OR e.status IN ('done','skipped') OR e.skip_state='pending' THEN RAISE EXCEPTION 'Skip request not applicable'; END IF; UPDATE public.task_executions SET skip_state='pending',skip_reason=_body WHERE id=_id;
ELSIF _action IN ('approve_skip','reject_skip') THEN IF NOT exec OR e.skip_state<>'pending' THEN RAISE EXCEPTION 'Executive approval required'; END IF; UPDATE public.task_executions SET skip_state=CASE WHEN _action='approve_skip' THEN 'approved' ELSE 'rejected' END,status=CASE WHEN _action='approve_skip' THEN 'skipped' ELSE status END WHERE id=_id;
ELSE RAISE EXCEPTION 'Invalid action'; END IF;
INSERT INTO public.task_execution_events(execution_id,actor_id,action,body) VALUES(_id,auth.uid(),_action,_body);
IF NOT e.recurring AND _action IN ('complete','reopen') THEN UPDATE public.tasks SET status=CASE WHEN _action='complete' THEN 'done'::public.task_status ELSE 'todo'::public.task_status END WHERE id=e.task_id; END IF; END $$;
CREATE OR REPLACE FUNCTION public.creator_set_task_status(_task_id uuid,_status public.task_status) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE eid uuid; BEGIN IF _status NOT IN ('todo','done') THEN RAISE EXCEPTION 'Only complete or reopen allowed'; END IF; SELECT id INTO eid FROM public.task_executions WHERE task_id=_task_id AND NOT recurring AND status<>'cancelled' ORDER BY created_at DESC LIMIT 1; IF eid IS NULL THEN RAISE EXCEPTION 'Use dated execution'; END IF; PERFORM public.task_execution_action(eid,CASE WHEN _status='done' THEN 'complete' ELSE 'reopen' END); END $$;
CREATE OR REPLACE FUNCTION public.save_task_configuration(_task_id uuid,_config jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid; rid uuid; start_date date; effective date; today date := (now() AT TIME ZONE 'America/Bogota')::date; mode text; state text; days integer[]; old_task public.tasks; affected uuid; BEGIN
IF NOT public.is_active_member(auth.uid()) OR NOT public.is_executive() THEN RAISE EXCEPTION 'Executive required'; END IF; PERFORM pg_advisory_xact_lock(7458321); PERFORM public.materialize_task_executions();
mode := coalesce(_config->>'recurrence','once'); state := coalesce(_config->>'recurrence_state','enabled'); SELECT coalesce(array_agg(value::integer),'{}') INTO days FROM jsonb_array_elements_text(coalesce(_config->'weekdays','[]'));
IF mode NOT IN ('once','daily','weekdays') OR state NOT IN ('enabled','paused','disabled') OR (mode='weekdays' AND cardinality(days)=0) OR EXISTS(SELECT 1 FROM unnest(days) d WHERE d<0 OR d>6) THEN RAISE EXCEPTION 'Invalid recurrence'; END IF;
IF nullif(trim(_config->>'title'),'') IS NULL THEN RAISE EXCEPTION 'Title required'; END IF; start_date := nullif(_config->>'due_date','')::date; IF mode<>'once' AND start_date IS NULL THEN RAISE EXCEPTION 'Recurring tasks need a start date'; END IF;
IF _task_id IS NOT NULL THEN SELECT * INTO old_task FROM public.tasks WHERE id=_task_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF; IF old_task.recurrence='once' AND EXISTS(SELECT 1 FROM public.task_executions WHERE task_id=_task_id AND status<>'cancelled' AND (scheduled_date<=today OR scheduled_date IS NULL OR status='done')) THEN RAISE EXCEPTION 'Historical task configuration is preserved'; END IF; END IF;
effective := CASE WHEN _task_id IS NULL THEN greatest(coalesce(start_date,today),today) ELSE greatest(coalesce(start_date,today+1),today+1) END;
IF _task_id IS NULL THEN INSERT INTO public.tasks(title,description,owner_id,creator_id,priority,due_date,due_time,recurrence,weekdays,recurrence_state,created_by) VALUES(trim(_config->>'title'),_config->>'description',nullif(_config->>'owner_id','')::uuid,nullif(_config->>'creator_id','')::uuid,coalesce(_config->>'priority','medium')::public.task_priority,start_date,nullif(_config->>'due_time','')::time,mode,days,state,auth.uid()) RETURNING id INTO tid;
ELSE tid := _task_id; UPDATE public.task_revisions SET effective_until=least(coalesce(effective_until,effective-1),effective-1) WHERE task_id=tid;
FOR affected IN UPDATE public.task_executions SET status='cancelled' WHERE task_id=tid AND scheduled_date>=effective AND status NOT IN ('done','cancelled') RETURNING id LOOP INSERT INTO public.task_execution_events(execution_id,actor_id,action) VALUES(affected,auth.uid(),'configuration_superseded'); END LOOP;
UPDATE public.tasks SET title=trim(_config->>'title'),description=_config->>'description',owner_id=nullif(_config->>'owner_id','')::uuid,creator_id=nullif(_config->>'creator_id','')::uuid,priority=coalesce(_config->>'priority','medium')::public.task_priority,due_date=start_date,due_time=nullif(_config->>'due_time','')::time,recurrence=mode,weekdays=days,recurrence_state=state WHERE id=tid; END IF;
INSERT INTO public.task_revisions(task_id,effective_from,title,description,owner_id,creator_id,priority,due_time,recurrence,weekdays,enabled) VALUES(tid,effective,trim(_config->>'title'),_config->>'description',nullif(_config->>'owner_id','')::uuid,nullif(_config->>'creator_id','')::uuid,coalesce(_config->>'priority','medium')::public.task_priority,nullif(_config->>'due_time','')::time,mode,days,state='enabled') RETURNING id INTO rid;
IF mode='once' THEN INSERT INTO public.task_executions(task_id,revision_id,scheduled_date,due_time,title,description,owner_id,creator_id,priority) SELECT task_id,id,start_date,due_time,title,description,owner_id,creator_id,priority FROM public.task_revisions WHERE id=rid; END IF; RETURN tid; END $$;
REVOKE ALL ON FUNCTION public.task_agenda(date),public.task_execution_action(uuid,text,text),public.save_task_configuration(uuid,jsonb),public.creator_set_task_status(uuid,public.task_status) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.task_agenda(date),public.task_execution_action(uuid,text,text),public.save_task_configuration(uuid,jsonb),public.creator_set_task_status(uuid,public.task_status) TO authenticated;